body, 
p, 
p *:not(span):not(icon):not(i):not(code), 
div *:not(span):not(icon):not(i):not(code) {
     font-family: Vazir !important;
     text-align: start !important;
}

article, 
article *:not(span):not(icon):not(i):not(code) {
    font-family: Vazir !important;
}

*:not(span):not(icon):not(i):not(code) {
    font-family: Vazir !important;
    text-align: start !important;
}
